    // TODO: 令 command=3，1 输出 Play，2 输出 Pause，其他输出 Stop

    return 0;
}

c4-4.solution:
#include <stdio.h>

int main(void) {
    int command = 3;
    switch (command) {
    case 1: puts("Play"); break;
    case 2: puts("Pause"); break;
    default: puts("Stop"); break;
    }
    return 0;
}

