#include <stdio.h>

int main(void) {
    // TODO: 令 s=60，先判断有效范围 0～100，再按及格线 60 输出 Invalid、Pass 或 Fail

    return 0;
}

c4-6.solution:
#include <stdio.h>

int main(void) {
    int s = 60;
    if (s < 0 || s > 100) { puts("Invalid"); }
    else if (s >= 60) { puts("Pass"); }
    else { puts("Fail"); }
    return 0;
}

