int main(void) {
    // TODO: 令 open=true、stock=5，营业且有货输出 Buy，营业无货输出 Sold out，不营业输出 Closed

    return 0;
}

c4-7.solution:
#include <stdio.h>
#include <stdbool.h>

int main(void) {
    bool open = true;
    int stock = 5;
    if (open) {
        if (stock > 0) { puts("Buy"); }
        else { puts("Sold out"); }
    } else { puts("Closed"); }
    return 0;
}
